mapper.select:
SELECT
b.`INSPECTION_PROCESS_ID`,
a.*
FROM
inspection.inspection_process_sub a
JOIN
inspection.inspection_process b
ON a.`PROCESS_ID` = b.`ID`
WHERE
1 = 1

    AND a.ID = #{params.ID}


    AND a.INSPECTION_PROCESS_SUB_ID = #{params.INSPECTION_PROCESS_SUB_ID}


    AND a.INSPECTION_PROCESS_SUB_NAME like '%${params.INSPECTION_PROCESS_SUB_NAME}%'


    AND a.PROCESS_ID = #{params.PROCESS_ID}


    AND a.INSPECTION_TASK_ID = #{params.INSPECTION_TASK_ID}


    AND a.INSPECTION_PROCESS_SUB_SIGN = #{params.INSPECTION_PROCESS_SUB_SIGN}


    AND a.FINISH_TIME = #{params.FINISH_TIME}


    AND a.IS_ACTIVE = #{params.IS_ACTIVE}


    AND a.FOR_RECORD = #{params.FOR_RECORD}

ORDER BY a.INSPECTION_PROCESS_SUB_ID

mapper.update:
UPDATE inspection.inspection_process SET
    INSPECTION_PROCESS_SIGN = (
    SELECT
    SUM(a.`INSPECTION_PROCESS_SUB_SIGN`) > 0
    FROM
        inspection.`inspection_process_sub` a
    WHERE
    a.`INSPECTION_TASK_ID` = #{params.INSPECTION_TASK_ID}
    AND a.INSPECTION_PROCESS_SUB_ID LIKE CONCAT(LEFT('${params.PROC_SUB_ID}', 5),'%')
    ),
INSPECTION_TASK_ID = #{params.INSPECTION_TASK_ID}
WHERE INSPECTION_TASK_ID = #{params.INSPECTION_TASK_ID}
AND INSPECTION_PROCESS_ID = LEFT('${params.PROC_SUB_ID}', 5)

UPDATE inspection.inspection_process_sub SET

    INSPECTION_PROCESS_SUB_SIGN = #{params.INSPECTION_PROCESS_SUB_SIGN},


    FINISH_TIME = #{params.FINISH_TIME},


    IS_ACTIVE = #{params.IS_ACTIVE},

ID = #{params.ID}
WHERE ID = #{params.ID}

UPDATE inspection.inspection_process_sub_postsv SET

    INSPECTION_PROCESS_SUB_SIGN = #{params.INSPECTION_PROCESS_SUB_SIGN},


    FINISH_TIME = #{params.FINISH_TIME},


    IS_ACTIVE = #{params.IS_ACTIVE},

ID = #{params.ID}
WHERE ID = #{params.ID}
